import * as T from './vendor/three.module.min.js';
const cache=new Map(),jobs=new Map(),waiting=new Map();
export function texture80(key,data=false){if(cache.has(key))return cache.get(key);let resolve,reject;const done=new Promise((a,b)=>{resolve=a;reject=b;});waiting.set(key,done);done.catch(()=>{});const t=new T.TextureLoader().load(new URL('./textures/tiki-v80/'+key+'.webp',import.meta.url).href,resolve,undefined,reject);t.colorSpace=data?T.NoColorSpace:T.SRGBColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;t.anisotropy=4;t.name='V80 generated '+key;cache.set(key,t);return t;}
export async function initializeTikiExterior80(){const keys=[...['fabric','rattan','walnut','bamboo','mask-left','mask-right'].flatMap(k=>['albedo','normal','roughness'].map(c=>'lounge/'+k+'-'+c)),'lounge/painting-albedo',...['areca','monstera','fern','bird-of-paradise'].map(k=>'exterior/'+k+'-albedo-512'),'exterior/sidewalk-albedo-1024','exterior/sidewalk-normal-512','exterior/sidewalk-roughness-512','jukebox/brushed-chrome-albedo','jukebox/brushed-chrome-normal','jukebox/red-vinyl-albedo'];let i=0;await Promise.all(Array.from({length:4},async()=>{while(i<keys.length){const key=keys[i++];texture80(key,/-normal(?:-512)?$|-roughness(?:-512)?$/.test(key));await waiting.get(key);}}));}

const sets={jukebox:['red-vinyl','bronze-grille','brushed-chrome','walnut'],lounge:['fabric','rattan','walnut','bamboo']};
export async function preload80(folder){if(jobs.has(folder))return jobs.get(folder);const p=(async()=>{const keys=folder==='jukebox'?[...sets.jukebox.flatMap(k=>['albedo','normal','roughness'].map(c=>folder+'/'+k+'-'+c)),folder+'/title-cards-packed',folder+'/decorative-band',folder+'/bronze-grille-mask']:[];let i=0;await Promise.all(Array.from({length:3},async()=>{while(i<keys.length){const key=keys[i++];if(cache.has(key)){await waiting.get(key);continue;}const t=await new T.TextureLoader().loadAsync(new URL('./textures/tiki-v80/'+key+'.webp',import.meta.url).href);t.colorSpace=/-normal$|-roughness$|-mask$/.test(key)?T.NoColorSpace:T.SRGBColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;t.anisotropy=4;t.name='V80 generated '+key;cache.set(key,t);}}));})();jobs.set(folder,p);return p;}
export function material80(folder,key,extra={}){return new T.MeshStandardMaterial({name:'V80 '+key,map:texture80(folder+'/'+key+'-albedo'),normalMap:texture80(folder+'/'+key+'-normal',true),roughnessMap:texture80(folder+'/'+key+'-roughness',true),normalScale:new T.Vector2(.22,.22),roughness:.8,...extra});}
export function jukeboxMaterials80(){const metal=material80('jukebox','brushed-chrome',{metalness:.53,roughness:.25,normalScale:new T.Vector2(.07,.07),envMapIntensity:1.05}),wood=material80('jukebox','walnut',{roughness:.65}),black=metal.clone();black.color.setHex(0x222329);black.metalness=.32;black.roughness=.44;return {jWood:wood,jChrome:metal,jBlack:black,jRed:material80('jukebox','red-vinyl',{roughness:.53,normalScale:new T.Vector2(.055,.055)}),jGrille:material80('jukebox','bronze-grille',{metalness:.62,roughness:.56,alphaMap:texture80('jukebox/bronze-grille-mask',true),alphaTest:.37,side:T.DoubleSide}),jGlow:new T.MeshBasicMaterial({name:'Steady amber speaker backlight',color:0xc67d28,toneMapped:false}),jPaper:new T.MeshStandardMaterial({map:texture80('jukebox/title-cards-packed'),roughness:.84,emissive:0xffedc3,emissiveMap:texture80('jukebox/title-cards-packed'),emissiveIntensity:.22}),jBand:new T.MeshStandardMaterial({map:texture80('jukebox/decorative-band'),roughness:.7,emissive:0xcadf95,emissiveMap:texture80('jukebox/decorative-band'),emissiveIntensity:.26}),jGlass:new T.MeshPhysicalMaterial({name:'Thin clear jukebox window',color:0xc8e1d8,metalness:.08,roughness:.12,transparent:true,opacity:.11,depthWrite:false,clearcoat:1,clearcoatRoughness:.1}),jIvory:new T.MeshStandardMaterial({color:0xddd4ba,roughness:.64,map:texture80('jukebox/brushed-chrome-albedo'),normalMap:texture80('jukebox/brushed-chrome-normal',true),normalScale:new T.Vector2(.025,.025)}),jWarm:new T.MeshBasicMaterial({color:0xe5dbb4,toneMapped:false})};}
